style.css:
@-moz-document domain("mail.google.com") {
/* Botón "Enviar" */
  div[role="button"][aria-label^="Enviar"],
  div[role="button"][data-tooltip^="Enviar"] {
    background-color: #ffbecb !important;
    border-color: #ffbecb !important;
    color: black !important;
  }

  /* Botón "Enviar" - Hover */
  div[role="button"][aria-label^="Enviar"]:hover,
  div[role="button"][data-tooltip^="Enviar"]:hover {
    filter: brightness(0.95);
  }

  /* Botón "Más opciones de envío" (ícono de flecha) */
  div[aria-label="Más opciones de envío"],
  div[aria-label="Más opciones de envío"][role="button"],
  div[role="button"][data-tooltip^="Más opciones de envío"] {
    background-color: #ffbecb !important;
    border-color: #ffbecb !important;
    color: black !important;
  }

  /* Hover en "Más opciones de envío" */
  div[aria-label="Más opciones de envío"]:hover,
  div[role="button"][data-tooltip^="Más opciones de envío"]:hover {
    filter: brightness(0.95);
  }
}
